 const selected=baseline?[baseline.trial,...(comparison?trials.filter(t=>comparison.trialIds.includes(String(t.trialId||''))):[])]:trials;
 const hypothesis=selected.some(t=>Boolean(text(t.hypothesis))),analysis=selected.some(t=>written(t.analysis)),conclusion=selected.some(t=>written(t.conclusion));
 const conditions=[{id:'hypothesis',met:hypothesis,reason:hypothesis?'LEARNER_TEXT_PRESENT_TIMING_NOT_CERTIFIED':'PREDICTION_MISSING'},{id:'setup-and-intervention',met:Boolean(baseline?.intervention.met),reason:baseline?.intervention.met?'ACCEPTED_PHYSICAL_TRANSFERS':'ACTIVITY_SPECIFIC_SETUP_AND_TRANSFER_NEEDED'},{id:'manual-series',met:Boolean(baseline),reason:baseline?'FIVE_SPACED_MANUAL_READINGS':'FIVE_VALID_SPACED_MANUAL_READINGS_NEEDED'},{id:'controlled-repeat',met:Boolean(comparison),reason:comparison?'CHANGED_VARIABLE_WITH_DOCUMENTED_CONTROLS':'COMPARABLE_REPEAT_NEEDED'},{id:'analysis',met:analysis,reason:analysis?'LEARNER_TEXT_PRESENT_NOT_GRADED':'ANALYSIS_MISSING'},{id:'conclusion',met:conclusion,reason:conclusion?'LEARNER_TEXT_PRESENT_NOT_GRADED':'CONCLUSION_MISSING'}];
 return {activity:id,conditions,counts:{trials:trials.length,totalRecordedManual:trials.reduce((n,t)=>n+(Array.isArray(t.readings)?t.readings.filter(r=>r?.method==='manual').length:0),0),manualReadings:entries.reduce((s,e)=>s+e.series.all.length,0),distinctTimes:entries.reduce((s,e)=>s+e.series.spaced.length,0),comparableTrials:comparison?2:0},comparison,observedActions:entries.map(e=>({trialId:String(e.trial.trialId||''),...e.intervention})),readyForTeacherReview:conditions.every(c=>c.met),teacherReview:'NOT TESTED',limitations:['Metadata checks do not certify authorship, prediction timing, scientific reasoning, teacher acceptance, device performance or L3 completion.']};
